 const identity=(title+' '+desc).toLowerCase().includes('@'+handle.toLowerCase());
 if(identity){const m=desc.match(/(?:^|\s)(\d[\d,.]*\s*[KMB]?)\s*(?:followers|subscribers)\b/i);if(m)return parseCount(m[1]);}
